CREATE FUNCTION public.validate_action_integrity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.causes; BEGIN IF NEW.cause_id IS NOT NULL THEN SELECT * INTO STRICT c FROM public.causes WHERE id=NEW.cause_id; IF (NEW.occurrence_id IS NOT NULL AND c.occurrence_id IS DISTINCT FROM NEW.occurrence_id) OR (NEW.problem_id IS NOT NULL AND c.problem_id IS DISTINCT FROM NEW.problem_id) THEN RAISE EXCEPTION 'A causa deve pertencer à ocorrência ou problema da ação'; END IF; END IF; IF NEW.status='done' AND length(trim(coalesce(NEW.evidence_note,'')))=0 AND NOT EXISTS(SELECT 1 FROM public.attachments WHERE action_id=NEW.id) THEN RAISE EXCEPTION 'A conclusão exige evidência'; END IF; IF TG_OP='UPDATE' AND auth.uid() IS NOT NULL AND public.current_app_role()='analyst' AND (NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.occurrence_id IS DISTINCT FROM OLD.occurrence_id OR NEW.problem_id IS DISTINCT FROM OLD.problem_id) THEN RAISE EXCEPTION 'Não é permitido alterar responsável ou vínculo'; END IF; RETURN NEW; END $$;
CREATE TRIGGER action_integrity BEFORE INSERT OR UPDATE ON public.actions FOR EACH ROW EXECUTE FUNCTION public.validate_action_integrity();
CREATE FUNCTION public.preserve_occurrence_audit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.first_response_breached:=OLD.first_response_breached OR NEW.first_response_breached; NEW.resolution_breached:=OLD.resolution_breached OR NEW.resolution_breached; NEW.protocol:=OLD.protocol; RETURN NEW; END $$;
CREATE TRIGGER occurrence_audit_preservation BEFORE UPDATE ON public.occurrences FOR EACH ROW EXECUTE FUNCTION public.preserve_occurrence_audit();
REVOKE ALL ON FUNCTION public.validate_action_integrity(),public.preserve_occurrence_audit(),public.initialize_occurrence_sla(),public.record_opening_event() FROM PUBLIC;
CREATE FUNCTION public.sla_tick() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.occurrences SET first_response_breached=true WHERE first_response_at IS NULL AND now()>first_response_due_at AND status NOT IN ('closed_resolved','closed_no_evaluation','closed_unfounded'); UPDATE public.occurrences SET resolution_breached=true WHERE now()>resolution_due_at AND status IN ('registered','in_analysis','in_treatment','reopened'); INSERT INTO public.sla_alerts(occurrence_id,alert_key) SELECT o.id,'res_'||threshold::text||'_c'||(o.reopen_count+1)::text FROM public.occurrences o JOIN public.accounts a ON a.id=o.account_id JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=o.severity CROSS JOIN unnest(ARRAY[50,80,100]) threshold WHERE o.status IN ('registered','in_analysis','in_treatment','reopened') AND public.business_minutes_between(a.calendar_id,o.resolution_started_at,now())-o.paused_business_minutes>=t.resolution_minutes*threshold/100 ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.sla_tick() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.sla_tick() TO service_role;